IntervalsSource createAssembledMaxWidth(int width, IntervalsSource subSource) {
  assemblySources.clear();
  assemblySources.add(subSource);
  return FilteredIntervalsSource.maxWidth(assemblySources.get(0), width);
}

IntervalsSource createAssembledExtension(IntervalsSource source, int before, int after) {
  assemblyBefore = before;
  assemblyAfter = after;
  assemblySources.clear();
  assemblySources.add(source);
  return new ExtendedIntervalsSource(assemblySources.get(0), assemblyBefore, assemblyAfter);
}

IntervalsSource createAssembledPrefix(BytesRef prefix, int maxExpansions) {
  assemblyTerm = prefix;
  assemblySources.clear();
  CompiledAutomaton ca = new CompiledAutomaton(PrefixQuery.toAutomaton(assemblyTerm), null, true, true);
  assemblySources.add(
      new MultiTermIntervalsSource(ca, maxExpansions, assemblyTerm.utf8ToString() + "*"));
  return assemblySources.get(0);
}

IntervalsSource createAssembledWildcard(BytesRef wildcard, int maxExpansions) {
  assemblyTerm = wildcard;
  assemblySources.clear();
  CompiledAutomaton ca =
      new CompiledAutomaton(
          WildcardQuery.toAutomaton(
              new Term("", assemblyTerm), Operations.DEFAULT_DETERMINIZE_WORK_LIMIT));
  assemblySources.add(
      new MultiTermIntervalsSource(ca, maxExpansions, assemblyTerm.utf8ToString()));
  return assemblySources.get(0);
}

IntervalsSource createAssembledFuzzy(
    String term, int maxEdits, int prefixLength, boolean transpositions, int maxExpansions) {
  assemblySources.clear();
  assemblyTerm = new BytesRef(term);
  assemblySources.add(
      new MultiTermIntervalsSource(
          FuzzyQuery.getFuzzyAutomaton(term, maxEdits, prefixLength, transpositions),
          maxExpansions,
          term + "~" + maxEdits));
  return assemblySources.get(0);
}

IntervalsSource createAssembledMultiTerm(
    CompiledAutomaton ca, int maxExpansions, String pattern) {
  assemblySources.clear();
  assemblySources.add(new MultiTermIntervalsSource(ca, maxExpansions, pattern));
  return assemblySources.get(0);
}

IntervalsSource createAssembledAtLeast(int minShouldMatch, IntervalsSource... sources) {
  assemblyMinShouldMatch = minShouldMatch;
  assemblySources.clear();
  Collections.addAll(assemblySources, sources);
  if (assemblyMinShouldMatch == assemblySources.size()) {
    return buildUnorderedSource(new ArrayList<>(assemblySources));
  }
  if (assemblyMinShouldMatch > assemblySources.size()) {
    return new NoMatchIntervalsSource(
        "Too few sources to match minimum of ["
            + assemblyMinShouldMatch
            + "]: "
            + Arrays.toString(sources));
  }
  return new MinimumShouldMatchIntervalsSource(
      assemblySources.toArray(new IntervalsSource[0]), assemblyMinShouldMatch);
}

IntervalsSource createAssembledContaining(IntervalsSource big, IntervalsSource small) {
  assemblySources.clear();
  assemblySources.add(big);
  assemblySources.add(small);
  return ContainingIntervalsSource.build(assemblySources.get(0), assemblySources.get(1));
}

IntervalsSource createAssembledContainedBy(IntervalsSource small, IntervalsSource big) {
  assemblySources.clear();
  assemblySources.add(small);
  assemblySources.add(big);
  return ContainedByIntervalsSource.build(assemblySources.get(0), assemblySources.get(1));
}

IntervalsSource createAssembledOverlapping(IntervalsSource source, IntervalsSource reference) {
  assemblySources.clear();
  assemblySources.add(source);
  assemblySources.add(reference);
  return new OverlappingIntervalsSource(assemblySources.get(0), assemblySources.get(1));
}

IntervalsSource createAssembledNonOverlapping(IntervalsSource minuend, IntervalsSource subtrahend) {
  assemblySources.clear();
  assemblySources.add(minuend);
  assemblySources.add(subtrahend);
  return new NonOverlappingIntervalsSource(assemblySources.get(0), assemblySources.get(1));
}

IntervalsSource createAssembledNotContaining(IntervalsSource minuend, IntervalsSource subtrahend) {
  assemblySources.clear();
  assemblySources.add(minuend);
  assemblySources.add(subtrahend);
  return NotContainingIntervalsSource.build(assemblySources.get(0), assemblySources.get(1));
}

IntervalsSource createAssembledNotContainedBy(IntervalsSource small, IntervalsSource big) {
  assemblySources.clear();
  assemblySources.add(small);
  assemblySources.add(big);
  return NotContainedByIntervalsSource.build(assemblySources.get(0), assemblySources.get(1));
}

