private static final float PHRASE_TO_SPAN_TERM_POSITIONS_COST = 4.0f;

public static float estimateTermPositionsCost(TermsEnum termsEnum) throws IOException {
  int docFreq = termsEnum.docFreq();
  assert docFreq > 0;
  long totalTermFreq = termsEnum.totalTermFreq();
  assert totalTermFreq > 0;
  float expOccurrencesInMatchingDoc = totalTermFreq / (float) docFreq;
  return TERM_POSNS_SEEK_OPS_PER_DOC + expOccurrencesInMatchingDoc * TERM_OPS_PER_POS;
}

static float estimateSpanTermPositionsCost(TermsEnum termsEnum) throws IOException {
  return estimateTermPositionsCost(termsEnum) * PHRASE_TO_SPAN_TERM_POSITIONS_COST;
}

static IntervalIterator createTermIntervals(BytesRef term, TermsEnum te) throws IOException {
  PostingsEnum pe = te.postings(null, PostingsEnum.POSITIONS);
  float cost = estimateTermPositionsCost(te);
  BytesRef copied = term;
    minExtent += subSource.minExtent();
  }
  return minExtent;
}

public static Spans combineNearSpans(int slop, boolean inOrder, List<Spans> subSpans)
    throws IOException {
  return (!inOrder)
      ? new NearSpansUnordered(slop, subSpans)
      : new NearSpansOrdered(slop, subSpans);
}

public static Spans createTermSpans(
    LeafSimScorer simScorer, PostingsEnum postings, Term term, float positionsCost) {
  return new TermSpans(simScorer, postings, term, positionsCost);
}

public static Spans createTermSpans(
    LeafReaderContext context,
    Term term,
    TermState state,
    SpanWeight.Postings requiredPostings,
    LeafSimScorer simScorer)
    throws IOException {
  if (state == null) {
    return null;
  }
  final Terms terms = context.reader().terms(term.field());
  if (terms == null) {
    return null;
  }
  if (terms.hasPositions() == false) {
    throw new IllegalStateException(
        "field \""
            + term.field()
            + "\" was indexed without position data; cannot run SpanTermQuery (term="
            + term.text()
            + ")");
  }
  final TermsEnum termsEnum = terms.iterator();
  termsEnum.seekExact(term.bytes(), state);
  final PostingsEnum postings = termsEnum.postings(null, requiredPostings.getRequiredPostings());
  float positionsCost = estimateSpanTermPositionsCost(termsEnum);
  return createTermSpans(simScorer, postings, term, positionsCost);
}

public static FilterSpans.AcceptStatus acceptExcludedSpan(
    Spans candidate,
    Spans excludeSpans,
    TwoPhaseIterator excludeTwoPhase,
    DocIdSetIterator excludeApproximation,
    int pre,
    int post,
    int[] lastApproxDoc,
    boolean[] lastApproxResult)
    throws IOException {
  int doc = candidate.docID();
  if (doc > excludeSpans.docID()) {
    if (excludeTwoPhase != null) {
      if (excludeApproximation.advance(doc) == doc) {
        lastApproxDoc[0] = doc;
        lastApproxResult[0] = excludeTwoPhase.matches();
      }
    } else {
      excludeSpans.advance(doc);
    }
  } else if (excludeTwoPhase != null
      && doc == excludeSpans.docID()
      && doc != lastApproxDoc[0]) {
    lastApproxDoc[0] = doc;
    lastApproxResult[0] = excludeTwoPhase.matches();
  }

  if (doc != excludeSpans.docID() || (doc == lastApproxDoc[0] && lastApproxResult[0] == false)) {
    return FilterSpans.AcceptStatus.YES;
  }

  if (excludeSpans.startPosition() == -1) {
    excludeSpans.nextStartPosition();
  }

  while (excludeSpans.endPosition() <= candidate.startPosition() - pre) {
    if (excludeSpans.nextStartPosition() == Spans.NO_MORE_POSITIONS) {
      return FilterSpans.AcceptStatus.YES;
    }
  }

  if (excludeSpans.startPosition() - post >= candidate.endPosition()) {
    return FilterSpans.AcceptStatus.YES;
  }
  return FilterSpans.AcceptStatus.NO;
}

static IntervalIterator expandMultiTerm(
    CompiledAutomaton automaton, Terms terms, int maxExpansions, String pattern)
    throws IOException {
  if (terms == null) {
    return null;
  }
  List<IntervalIterator> subSources = new ArrayList<>();
  TermsEnum te = automaton.getTermsEnum(terms);
  BytesRef term;
  int count = 0;
  while ((term = te.next()) != null) {
    subSources.add(createTermIntervals(term, te));
    if (++count > maxExpansions) {
      throw new IllegalStateException(
          "Automaton [" + pattern + "] expanded to too many terms (limit " + maxExpansions + ")");
    }
  }
  if (subSources.size() == 0) {
    return null;
  }
  return new DisjunctionIntervalsSource.DisjunctionIntervalIterator(subSources);
}

static IntervalsSource buildRepeatingSource(IntervalsSource in, int childCount) {
  if (childCount == 1) {
    return in;
  }
  assert childCount > 0;

